const registros = $input.all();

// Data atual no horário de Recife
const hoje = new Date().toLocaleDateString("pt-BR", {
  timeZone: "America/Recife"
});

// Filtra apenas os registros cuja data_saida seja hoje
const encontrados = registros.filter(item => {
  const data = String(item.json.data_saida || "").trim();
  return data === hoje;
});

// Ordena pelo horário, do mais recente para o mais antigo
encontrados.sort((a, b) => {
  const horaA = String(a.json.horario_saida || "00:00");
  const horaB = String(b.json.horario_saida || "00:00");
  return horaB.localeCompare(horaA);
});

// Se não houver registros hoje
if (!encontrados.length) {
  return [{
    json: {
      data: hoje,
      total: 0,
      registros: []
    }
  }];
}

// Retorna tudo em um único item
return [{
  json: {
    data: hoje,
    total: encontrados.length,
    registros: encontrados.map(item => ({
      nome_aluno: item.json.nome_aluno,
      turma: item.json.turma,
      responsavel: item.json.responsavel,
      data_saida: item.json.data_saida,
      horario_saida: item.json.horario_saida,
      motivo: item.json.motivo,
      status: item.json.status,
      data_registro: item.json.data_registro
    }))
  }
}];
